ALTER TABLE public.assignment_submissions ADD COLUMN files jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.course_notices ADD COLUMN pinned boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX one_pinned_notice_per_course ON public.course_notices(course_slug) WHERE pinned;
CREATE POLICY "Learners and instructors read assignment files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'assignment-work' AND ((auth.uid()::text = (storage.foldername(name))[2] AND public.in_course(auth.uid(), (storage.foldername(name))[1])) OR public.teaches(auth.uid(), (storage.foldername(name))[1])) AND EXISTS (SELECT 1 FROM public.assignments a WHERE a.id::text = (storage.foldername(name))[3] AND a.course_slug = (storage.foldername(name))[1]));
CREATE POLICY "Learners upload own assignment files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'assignment-work' AND auth.uid()::text = (storage.foldername(name))[2] AND public.in_course(auth.uid(), (storage.foldername(name))[1]) AND EXISTS (SELECT 1 FROM public.assignments a WHERE a.id::text = (storage.foldername(name))[3] AND a.course_slug = (storage.foldername(name))[1]));
CREATE POLICY "Learners remove own assignment files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'assignment-work' AND auth.uid()::text = (storage.foldername(name))[2] AND public.in_course(auth.uid(), (storage.foldername(name))[1]));
CREATE OR REPLACE FUNCTION public.guard_assignment_marking() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE max_marks integer; BEGIN SELECT max_score INTO max_marks FROM public.assignments WHERE id = NEW.assignment_id; IF NEW.score IS NOT NULL AND (NEW.score < 0 OR NEW.score > max_marks) THEN RAISE EXCEPTION 'Mark must be between 0 and %', max_marks; END IF; IF NEW.status NOT IN ('submitted','marked','graded') THEN RAISE EXCEPTION 'Invalid submission status'; END IF; IF NEW.status = 'graded' AND NEW.score IS NULL THEN RAISE EXCEPTION 'A mark is required before returning work'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_assignment_marking BEFORE INSERT OR UPDATE ON public.assignment_submissions FOR EACH ROW EXECUTE FUNCTION public.guard_assignment_marking();